import{_ as l,o as i,c as t,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-10-23 :: Ceph Science User Group Meeting","description":"","frontmatter":{"title":"2019-10-23 :: Ceph Science User Group Meeting","date":"2019-10-23T00:00:00.000Z","updated":"2019-11-01T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[集群管理]","[存储优化]","[性能提升]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-23_-_-_Ceph_Science_User_Group_Meeting.md","filePath":"posts/2019/2019-10-23_-_-_Ceph_Science_User_Group_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-10-23_-_-_Ceph_Science_User_Group_Meeting.md"};function s(r,e,_,n,a,u){return i(),t("div",null,[...e[0]||(e[0]=[p("<p>本次会议主要讨论了Ceph集群的运行状况、升级经验、新技术等话题，以下为会议内容的详细总结：</p><p><strong>一、CERN CEPhta项目</strong></p><ul><li>CERN的CEPhta项目取得了显著成果，感谢Dan和Julian的贡献。</li><li>项目视频中存在部分视频长度不正确的问题，正在修复中，修复后将上传至YouTube。</li></ul><p><strong>二、集群规模与性能</strong></p><ul><li>讨论了单一大集群与多个小集群的优缺点，不同用户有不同的偏好。</li><li>讨论了OSD map更新时间随集群规模增长的情况，目前没有遇到明显问题。</li></ul><p><strong>三、存储类型与配置</strong></p><ul><li>讨论了S3存储与块存储分离的配置，以避免混合使用场景。</li><li>讨论了使用CHAP代理进行QoS控制，以防止S3用户占用过多资源。</li><li>讨论了使用ZRAM压缩交换空间，以增加服务器内存使用效率。</li></ul><p><strong>四、Ceph Nautilus版本升级</strong></p><ul><li>多位用户分享了从Mimic升级到Nautilus的经验，包括升级过程、遇到的问题和解决方案。</li><li>讨论了在Nautilus版本1424中发现的bug，并等待修复。</li></ul><p><strong>五、Ceph Seth使用经验</strong></p><ul><li>Rafael分享了他们公司使用Ceph Seth的经验，包括集群规模、使用场景和升级计划。</li><li>讨论了S3集群之间的复制、多区域S3和灾难恢复等话题。</li></ul><p><strong>六、其他讨论</strong></p><ul><li>讨论了使用NVMe卡作为rocksdb存储的配置，包括RAID配置和性能监控。</li><li>讨论了使用Ceph文件系统（CephFS）与高性能计算（HPC）集群的集成。</li><li>讨论了使用Condor调度器在空闲CPU上运行Ceph工作负载。</li></ul><p><strong>七、后续行动计划</strong></p><ul><li>确定下一次会议时间（预计为1月份）。</li><li>继续关注Ceph社区动态和bug修复。</li></ul><p><strong>改进点</strong>：</p><ol><li>在“CERN CEPhta项目”部分，增加了对视频长度问题的描述。</li><li>在“集群规模与性能”部分，增加了对OSD map更新时间的讨论。</li><li>在“Ceph Nautilus版本升级”部分，增加了对bug修复的讨论。</li><li>在“Ceph Seth使用经验”部分，增加了对S3集群之间复制的讨论。</li><li>在“其他讨论”部分，增加了对使用NVMe卡、CephFS和Condor调度器的讨论。</li></ol><p>通过以上改进，更准确地反映了原始内容的要点，并涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>",18)])])}const g=l(o,[["render",s]]);export{c as __pageData,g as default};
